package com.aoo.bcg.common.cache;
import com.aoo.bcg.gamespi.time.AuthoritativeTimeSource;import java.time.Duration;import java.time.Instant;import java.util.Objects;import java.util.Optional;
/** Time-bounded read-old/copy-new migration. Writes are new-key-only; dual-write is impossible. */
public final class ReadThroughCacheMigration{private final CacheAccessor cache;private final AuthoritativeTimeSource time;private final Instant legacyReadCutoff;public ReadThroughCacheMigration(CacheAccessor cache,AuthoritativeTimeSource time,Instant legacyReadCutoff){this.cache=Objects.requireNonNull(cache);this.time=Objects.requireNonNull(time);this.legacyReadCutoff=Objects.requireNonNull(legacyReadCutoff);}public Optional<String>read(CacheKey target,String legacyKey,Duration remainingTtl){Optional<String>current=cache.get(target.value());if(current.isPresent())return current;if(!time.now().isBefore(legacyReadCutoff))return Optional.empty();Optional<String>legacy=cache.get(legacyKey);legacy.ifPresent(value->cache.set(target.value(),value,remainingTtl));return legacy;}public void write(CacheKey target,String value,Duration ttl){cache.set(target.value(),value,ttl);}public boolean legacyReadsEnabled(){return time.now().isBefore(legacyReadCutoff);}}
